package com.nextaicommerce.platform.fba;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import java.util.*;import java.time.*;import org.springframework.jdbc.core.JdbcTemplate;
class FbaChildObservationsTest {
 Map<String,Object> row(String reference,String sku,int shipped,int received,boolean complete){return Map.of("shipment_id",reference,"seller_sku",sku,"quantity_shipped",shipped,"quantity_received",received,"items_complete",complete,"observed_at","2026-11-18T00:00:00Z","evidence_version","1","item_evidence","[{\"SellerSKU\":\""+sku+"\",\"QuantityShipped\":"+shipped+",\"QuantityReceived\":"+received+"}]");}
 final FbaInboundWorkflow.Child child=new FbaInboundWorkflow.Child("api-child",Map.of("SKU",4),"FBA-verified");
 @Test void genuineConfirmationReferenceMatchesImportedEvidenceWithoutChangingOperationalContents(){var result=FbaChildObservations.project(List.of(child),List.of(row("FBA-verified","SKU",4,3,true))).get(child.shipmentId());assertEquals(4,result.shipped());assertEquals(3,result.received());assertEquals(Instant.parse("2026-11-18T00:00:00Z"),result.observedAt());assertNull(result.issue());assertEquals(Map.of("SKU",4),child.skuUnits());}
 @Test void missingOrPartialOrDifferentSkuEvidenceRemainsUnknown(){for(var rows:List.of(List.<Map<String,Object>>of(),List.of(row("FBA-verified","SKU",4,0,false)),List.of(row("FBA-verified","OTHER",4,3,true)),List.of(row("unrelated","SKU",4,3,true)))){var result=FbaChildObservations.project(List.of(child),rows).get(child.shipmentId());assertNull(result.shipped());assertNull(result.received());assertNotNull(result.issue());}}
 @Test void ambiguousApiAndConfirmationRowsNeverDoubleCount(){var result=FbaChildObservations.project(List.of(child),List.of(row("api-child","SKU",4,3,true),row("FBA-verified","SKU",4,3,true))).get(child.shipmentId());assertNull(result.received());assertTrue(result.issue().contains("review"));}
 @Test void completeZeroReceivedIsGenuineZero(){assertEquals(0,FbaChildObservations.project(List.of(child),List.of(row("FBA-verified","SKU",4,0,true))).get(child.shipmentId()).received());}
 @Test void lookupIsOneBoundedTenantAndStoreQueryWithExactReferences(){var jdbc=mock(JdbcTemplate.class);UUID tenant=UUID.randomUUID(),store=UUID.randomUUID();new FbaChildObservations(jdbc).read(tenant,store,List.of(child));var sql=org.mockito.ArgumentCaptor.forClass(String.class);var args=org.mockito.ArgumentCaptor.forClass(Object[].class);verify(jdbc).queryForList(sql.capture(),args.capture());assertTrue(sql.getValue().contains("s.tenant_id=? AND s.marketplace_connection_id=? AND s.shipment_id IN"));assertTrue(sql.getValue().contains("i.tenant_id=s.tenant_id AND i.marketplace_connection_id=s.marketplace_connection_id"));assertEquals(List.of(tenant,store,"api-child","FBA-verified"),Arrays.asList(args.getValue()));verify(jdbc,never()).update(anyString(),any(Object[].class));}
 @Test void emptyPlanDoesNotQueryAndOversizedLookupFailsClosed(){var jdbc=mock(JdbcTemplate.class);var repo=new FbaChildObservations(jdbc);assertEquals(Map.of(),repo.read(UUID.randomUUID(),UUID.randomUUID(),List.of()));assertThrows(IllegalArgumentException.class,()->repo.read(UUID.randomUUID(),UUID.randomUUID(),Collections.nCopies(1001,child)));verifyNoInteractions(jdbc);}
 @Test void actualPostgresTimestampIsRetained(){var r=new HashMap<>(row("FBA-verified","SKU",4,3,true));r.put("observed_at","2026-11-18 01:02:03.123456+00");assertEquals(Instant.parse("2026-11-18T01:02:03.123456Z"),FbaChildObservations.project(List.of(child),List.of(r)).get(child.shipmentId()).observedAt());}
 @Test void sameSkuPartialRefreshCannotUseOldCompletionMarker(){var r=new HashMap<>(row("FBA-verified","SKU",4,3,true));r.put("quantity_received",4);var result=FbaChildObservations.project(List.of(child),List.of(r)).get(child.shipmentId());assertNull(result.received());assertNull(result.shipped());}
 @Test void missingCompletedSnapshotOrUnparseableDateKeepsQuantitiesUnknown(){for(String key:List.of("item_evidence","evidence_version","observed_at")){var r=new HashMap<>(row("FBA-verified","SKU",4,3,true));r.remove(key);assertNull(FbaChildObservations.project(List.of(child),List.of(r)).get(child.shipmentId()).received());}}
}
